import re, glob, os
from datetime import date, timedelta

files = sorted(glob.glob('/app/logs/*.log'))
sev_re = re.compile(r'\[(ERROR|WARNING|INFO|DEBUG|CRITICAL|ALERT|EMERGENCY|FATAL|NOTICE|TRACE|SEVERE|NOTICE)\]')

def sev_of(line):
    m = re.match(r'^(\d{4}-\d{2}-\d{2}) \d{2}:\d{2}:\d{2} \[([^\]]+)\]', line)
    return m.group(2) if m else None

def file_date(path):
    return path.split('/')[-1].split('_')[0]

counts = {}  # date -> {sev: n}
for f in files:
    d = file_date(f)
    counts.setdefault(d, {'ERROR':0,'WARNING':0,'INFO':0})
    with open(f) as fh:
        for line in fh:
            s = sev_of(line.strip())
            if s in ('ERROR','WARNING','INFO'):
                counts[d][s] += 1

ref = date(2025,8,12)
def in_range(d, start, end):
    return start <= d <= end

def total_for(sev):
    t = 0
    for f in files:
        with open(f) as fh:
            for line in fh:
                s = sev_of(line.strip())
                if s == sev:
                    t += 1
    return t

def range_counts(start, end):
    c = {'ERROR':0,'WARNING':0,'INFO':0}
    for d, v in counts.items():
        if start <= d <= end:
            for k in c: c[k]+=v[k]
    return c

today = ref
last7_start = ref - timedelta(days=6)
last30_start = ref - timedelta(days=29)
month_start = date(ref.year, ref.month, 1)

rows = []
for period, (start, end) in [
    ('today', (today, today)),
    ('last_7_days', (last7_start, today)),
    ('last_30_days', (last30_start, today)),
    ('month_to_date', (month_start, today)),
]:
    c = range_counts(start, end)
    for sev in ('ERROR','WARNING','INFO'):
        rows.append((period, sev, c[sev]))
c = {'ERROR':0,'WARNING':0,'INFO':0}
for d, v in counts.items():
    for k in c: c[k]+=v[k]
for sev in ('ERROR','WARNING','INFO'):
    rows.append(('total', sev, c[sev]))

with open('/app/summary.csv','w') as fh:
    fh.write('period,severity,count\n')
    for p,s,cnt in rows:
        fh.write(f'{p},{s},{cnt}\n')

# debug dump
print('per-day range sample:', {d:counts[d] for d in sorted(counts)[-3:]})
